<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card"><div class="card-header"><h1>Wishlist</h1><p>Save vendor items to consider stocking later.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<?php if(!$wishlist):?><p class="muted">Wishlist empty.</p><?php else:?><table class="data-table"><tr><th>WID</th><th>Vendor Product</th><th>Price</th><th>Vendor</th><th>Policy</th><th>Remove</th></tr><?php foreach($wishlist as $w):?><tr><td>#<?php echo e($w['wid']);?></td><td><?php echo e($w['name']);?></td><td>TK <?php echo e(number_format((float)$w['price'],2));?></td><td><?php echo e($w['vendor_name']);?></td><td class="small"><?php echo $w['return_policy']?e(mb_strimwidth($w['return_policy'],0,35,'...')):'—';?></td><td><form method="post" action="<?php echo e(url_for('seller','wishlist'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="remove"><input type="hidden" name="wishlist_id" value="<?php echo e($w['wid']);?>"><button class="btn btn-secondary btn-small">Remove</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
<div class="card"><div class="card-header"><h2>Vendor Supply</h2></div><?php if(!$vendor_products):?><p class="muted">No vendor products yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Name</th><th>Price</th><th>Vendor</th><th>Save</th></tr><?php foreach($vendor_products as $vp):?><tr><td>#<?php echo e($vp['id']);?></td><td><?php echo e($vp['name']);?></td><td>TK <?php echo e(number_format((float)$vp['price'],2));?></td><td><?php echo e($vp['vendor_name']);?></td><td><form method="post" action="<?php echo e(url_for('seller','wishlist'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="add"><input type="hidden" name="vendor_product_id" value="<?php echo e($vp['id']);?>"><button class="btn btn-primary btn-small">Save</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
<?php require __DIR__ . '/../partials/footer.php'; ?>
